package com.aicap.controller;
import com.aicap.planning.ImpactAnalysisService; import com.aicap.planning.PlanningAgentService; import com.aicap.security.Roles; import com.aicap.service.ProjectAccessService; import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.node.ObjectNode; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/planning-agent") @RequiredArgsConstructor public class PlanningAgentController {private final PlanningAgentService service;private final ImpactAnalysisService impactAnalysis; private final ProjectAccessService projectAccess;@PostMapping("/runs") public Map<String,Object> create(@RequestBody JsonNode b){String rawProject=b.has("project_id")?b.path("project_id").asText(""):b.path("projectId").asText("");String projectId=ProjectAccessService.normalize(rawProject); projectAccess.requireMember(projectId); return service.create(projectId,b.path("request").asText(""),Roles.any());}@GetMapping("/runs/{id}") public Map<String,Object> get(@PathVariable String id,@RequestParam String projectId){Roles.any();String scopedProjectId=ProjectAccessService.normalize(projectId);projectAccess.requireMember(scopedProjectId);return service.get(id,scopedProjectId);}@PostMapping("/runs/{id}/confirm") public Map<String,Object> confirm(@PathVariable String id,@RequestParam String projectId){String scopedProjectId=ProjectAccessService.normalize(projectId);projectAccess.requireWriter(scopedProjectId);return service.confirm(id,scopedProjectId,Roles.writer());}@PostMapping("/runs/{id}/cancel") public Map<String,Object> cancel(@PathVariable String id,@RequestParam String projectId){String scopedProjectId=ProjectAccessService.normalize(projectId);projectAccess.requireWriter(scopedProjectId);return service.cancel(id,scopedProjectId);}@PostMapping("/impact") public ObjectNode impact(@RequestBody ObjectNode plan){Roles.any();String rawProject=plan.has("project_id")?plan.path("project_id").asText(""):plan.path("projectId").asText("");String projectId=ProjectAccessService.normalize(rawProject); projectAccess.requireMember(projectId); return impactAnalysis.analyze(projectId,plan);}}
